		TMultiMap(TMultiMap&&) = default;
		TMultiMap(const TMultiMap&) = default;
		TMultiMap& operator=(TMultiMap&&) = default;
		TMultiMap& operator=(const TMultiMap&) = default;

		TMultiMap(std::initializer_list<ElementType> InitList)
		{
			this->Reserve(static_cast<int32>(InitList.size()));
			for (const ElementType& Element : InitList)
			{
				Add(Element.Key, Element.Value);
			}
		}

		/** Adds a pair, whether or not the key is already present. */
		inline ValueType& Add(const KeyType&  InKey, const ValueType&  InValue) { return Emplace(InKey, InValue); }
		inline ValueType& Add(const KeyType&  InKey,       ValueType&& InValue) { return Emplace(InKey, MoveTempIfPossible(InValue)); }
		inline ValueType& Add(      KeyType&& InKey, const ValueType&  InValue) { return Emplace(MoveTempIfPossible(InKey), InValue); }
		inline ValueType& Add(      KeyType&& InKey,       ValueType&& InValue) { return Emplace(MoveTempIfPossible(InKey), MoveTempIfPossible(InValue)); }

		template <typename InitKeyType, typename InitValueType>
		ValueType& Emplace(InitKeyType&& InKey, InitValueType&& InValue)
		{
			const FSetElementId PairId = this->Pairs.Emplace(ElementType(Forward<InitKeyType>(InKey), Forward<InitValueType>(InValue)));
			return this->Pairs[PairId].Value;
		}

		/** Appends every value mapped to Key to OutValues. */
		template <typename Allocator>
		void MultiFind(KeyInitType Key, TArray<ValueType, Allocator>& OutValues, bool bMaintainOrder = false) const
		{
			const int32 StartIndex = OutValues.Num();

			for (const ElementType& Pair : this->Pairs)
			{
				if (KeyFuncs::Matches(KeyFuncs::GetSetKey(Pair), Key))
				{
					OutValues.Add(Pair.Value);
				}
			}

			if (bMaintainOrder)
			{
				// The set walks its elements in index order, which is the reverse of the order the
				// hash chain would give; reversing puts them back in insertion order.
				const int32 NumResults = OutValues.Num() - StartIndex;
				for (int32 Offset = 0; Offset < NumResults / 2; ++Offset)
				{
					OutValues.Swap(StartIndex + Offset, OutValues.Num() - 1 - Offset);
				}
			}
		}

